export function Icon({
  name,
  size = 24,
  color,
  style,
}: {
  name: IconName;
  size?: number;
  color?: string;
  style?: React.CSSProperties;
}) {
  const id = useId();
  // the AI mark is always its own blue-to-violet, whatever colour the row around it uses
  const ai = name === "sparkles";
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      aria-hidden="true"
      style={{ display: "block", flex: "0 0 auto", color: color === "tone" ? "var(--sd-icon-accent)" : color, ...style }}
    >
      {ai && (
        <defs>
          <linearGradient id={id} x1="2" y1="2" x2="22" y2="22" gradientUnits="userSpaceOnUse">
            <stop stopColor="#2563EB" />
            <stop offset="1" stopColor="#9333EA" />
          </linearGradient>
        </defs>
      )}
      <path d={PATHS[name]} fill={ai ? `url(#${id})` : "currentColor"} />
    </svg>
  );
}
